local ServiceCollection = require(script.Parent.Parent.DependencyInjection.ServiceCollection)
local ServiceProvider = require(script.Parent.Parent.DependencyInjection.ServiceProvider)
local HostingEnvironment = require(script.Parent.HostingEnvironment)
local InternalHost = require(script.Parent.InternalHost)
local ConfigurationBuilder = require(script.Parent.Parent.Configuration.ConfigurationBuilder)
local HostBuilderContext = require(script.Parent.HostBuilderContext)
local LoggerManager = require(game.ReplicatedStorage.Packages.LoggerManager)
local ExtensionsWrapper = require(script.Parent.Parent.ExtensionsWrapper)
local InstancePathManager = require(script.Parent.Parent.InstancePathManager)

--[=[
    @class HostBuilder

    主机构建者
]=]
local HostBuilder = {}
HostBuilder.__index = HostBuilder

local Logger: ILogger = LoggerManager.GetLogger("TangSeng")

local function createServiceCollection()
	local s = ServiceCollection.new()
	ExtensionsWrapper.Wrap("IServiceCollection", s)
	return s
end

--- 构建一个 HostBuilder
--- @param luaTypePrivider ILuaTypeProvider -- Lua类型提供器
function HostBuilder.new(luaTypePrivider: ILuaTypeProvider): IHostBuilder
	assert(luaTypePrivider, "luaTypePrivider is required")
	local self = setmetatable({}, HostBuilder)
	self.Services = createServiceCollection()
	self._configureHostConfigActions = {}
	self._configureHostingEnvironmentActions = {}
	self._configureAppConfigActions = {}
	self._configureServicesActions = {}
	self._configureContainerActions = {}
	self._hostBuilt = false
	self._luaTypeProvider = luaTypePrivider
	self.Properties = {
		LuaTypeProvider = luaTypePrivider,
	}
	return self
end

--- 配置主机配置
function HostBuilder:ConfigureHostConfiguration(configureDelegate: (configBuilder: IConfigurationBuilder) -> ())
	table.insert(self._configureHostConfigActions, configureDelegate)
	return self
end

--- 配置应用配置
function HostBuilder:ConfigureAppConfiguration(handler: (
	hostBuilderContext: IHostBuilderContext,
	configurationBuilder: IConfigurationBuilder
) -> ())
	table.insert(self._configureAppConfigActions, handler)
	return self
end

--- 配置环境变量
function HostBuilder:ConfigureHostingEnvironment(
	handlerOrTable: table | (hostingEnvironment: IHostingEnvironment) -> ()
)
	local type = type(handlerOrTable)

	if type == "function" then
		local handler = handlerOrTable
		table.insert(self._configureHostingEnvironmentActions, handler)
	elseif type == "table" then
		table.insert(self._configureHostingEnvironmentActions, function()
			local table = handlerOrTable
			for key, value in pairs(table) do
				self._hostingEnvironment:UpdateProperty(key, value)
			end
		end)
	end

	return self
end

--- 配置服务
function HostBuilder:ConfigureServices(handler: (
	hostBuilderContext: IHostBuilderContext,
	services: IServiceCollection
) -> ())
	table.insert(self._configureServicesActions, handler)
	return self
end

--- 构建
function HostBuilder:Build(): IHost
	if self._hostBuilt then
		error("BuildCalled")
	end
	self._hostBuilt = true

	self:__InitializeHostConfiguration()
	self:__InitializeHostingEnvironment()
	self:__InitializeHostBuilderContext()
	self:__InitializeAppConfiguration()
	self:__InitializeServiceProvider()
	Logger.verbose(function(name)
		print(name, `HostBuilder 构建完成`)
	end)
	return self:__ResolveHost(self._appServices)
end

function HostBuilder:__InitializeHostConfiguration()
	local configBuilder = ConfigurationBuilder.new()
	for _, configureHostConfig in ipairs(self._configureHostConfigActions) do
		configureHostConfig(configBuilder)
	end
	self._hostConfiguration = configBuilder:Build()
end

function HostBuilder:__InitializeHostingEnvironment()
	self._hostingEnvironment = HostingEnvironment.new()
	self._hostingEnvironment.LuaTypeProvider = self._luaTypeProvider

	for _, handler in ipairs(self._configureHostingEnvironmentActions) do
		handler(self._hostingEnvironment)
	end

	-- set to _G
	_G.tangsengEnv = self._hostingEnvironment

	-- self._hostingEnvironment:Initialize(
	-- 	self._hostConfiguration:GetValue(HostDefaults.ContentRootKey) or Directory.GetCurrentDirectory(),
	-- 	self._hostConfiguration:GetValue(HostDefaults.EnvironmentKey)
	-- )
	-- self._hostingEnvironment.ApplicationName = self._hostConfiguration:GetValue(HostDefaults.ApplicationKey)
	-- 	or Assembly.GetEntryAssembly().GetName().Name
end

function HostBuilder:__InitializeHostBuilderContext()
	self._hostBuilderContext = HostBuilderContext.new()
	self._hostBuilderContext.Configuration = self._hostConfiguration
	self._hostBuilderContext.HostingEnvironment = self._hostingEnvironment
	self._hostBuilderContext.Properties = self.Properties
	self._hostBuilderContext.LuaTypeProvider = self._luaTypeProvider
end

function HostBuilder:__InitializeAppConfiguration()
	local configBuilder = ConfigurationBuilder.new()
	for _, configureHostConfig in ipairs(self._configureAppConfigActions) do
		configureHostConfig(self._hostBuilderContext, configBuilder)
	end
	self._appConfiguration = configBuilder:Build()
end

function HostBuilder:__InitializeServiceProvider()
	local services = self.Services

	self:__PopulateServiceCollection(services)
	services:AddSingleton("IHostingEnvironment", function()
		return self._hostingEnvironment
	end)
	services:AddSingleton("ILoggerManager", function()
		return LoggerManager
	end)
	services:AddSingleton("InstancePathManager", function()
		return InstancePathManager
	end)
	services:AddSingleton("SLogger", function()
		local loggerManagerIns = game.ReplicatedStorage.Packages.LoggerManager
		local SLoggerIns = loggerManagerIns.SLogger.SLogger:Clone()
		local SLogger = require(SLoggerIns)
		SLogger.Init(nil, require(loggerManagerIns), require(loggerManagerIns.SLogger.SystemNameCache))
		SLoggerIns:Destroy()
		return SLogger
	end)
	services:AddSingleton("ILuaTypeProvider", function()
		return self._luaTypeProvider
	end)
	services:AddSingleton("IConfiguration", self._appConfiguration)
	-- services:AddSingleton(self._hostConfiguration)

	for _, configureServices in ipairs(self._configureServicesActions) do
		configureServices(self._hostBuilderContext, services)
	end

	-- self._appServices = services:BuildServiceProvider()
	self._appServices = ServiceProvider.new(nil, services, self._luaTypeProvider)
end

function HostBuilder:__PopulateServiceCollection(serviceCollection: IServiceCollection)
	serviceCollection:AddSingleton("IHost", function(services)
		return InternalHost.new(services)
	end)
	serviceCollection:AddSingleton("IHostServicesBootstrap", script.Parent.HostServicesBootStrap)

	-- activator
	serviceCollection:AddScoped("IActivator", script.Parent.Parent.DependencyInjection.ActivatorUtilities.Activator)
	serviceCollection:AddSingleton("IActivatorUtilities", script.Parent.Parent.DependencyInjection.ActivatorUtilities)
end

function HostBuilder:__ResolveHost(serviceProvider)
	local host = serviceProvider:GetService("IHost")
	if not host then
		error("HostFactoryResolutionFailed")
	end

	return host
end

export type Type = typeof(HostBuilder.new())

return HostBuilder
